cd multicode/duckpit/gloryholes/Assets/Game/Code; python3 - <<'EOF'
p='OnePit/Ui/HallUpgSheet.cs'
s=open(p,encoding='utf-8').read()
a=s.index('        SegBar BuildBar(RectTransform c)')
b=s.index('        static string BarText(SegBar b)')
new='''        SegBar BuildBar(RectTransform c)
        {
            var b = new SegBar { Seg = new Image[SegMax], Lock = new Image[SegMax], Fill = new Image[SegMax], State = new char[SegMax] };
            b.Root = UiKit.Box("Segs", c, new Vector2(530f, 22f), new Vector2(0.5f, 0.5f), new Vector2(-330f + 265f, SegY));
            for (int i = 0; i < SegMax; i++)
            {
                b.Seg[i] = U.Img(b.Root, UiKit.RoundedSprite(7), _slot, new Vector2(SegW, SegH), Vector2.zero, "Seg" + i);
                b.Fill[i] = U.Img(b.Seg[i].rectTransform, UiKit.RoundedSprite(7), _segGreen, new Vector2(SegW, SegH), Vector2.zero, "Part");
                b.Lock[i] = U.IconImg(b.Seg[i].rectTransform, Icon.Lock, 15f, new Vector2(0f, 1f), "Lock");
                b.Lock[i].color = _lockName;
                b.Seg[i].gameObject.SetActive(false);
            }
            b.Root.gameObject.SetActive(false);
            return b;
        }

        /// Сегменты lv / cap / next. До SegMax уровней — сегмент на уровень, щель после каждых 5; лестница длиннее (Цена утки: 30 в главе I,
        /// 130 к концу главы II) — сегмент на 5 уровней (начатая пятёрка — серая с зелёной частью), окно ≤ SegMax пятёрок вокруг купленного.
        void SetBar(SegBar b, int lv, int cap, int next, Color green)
        {
            if (b == null) return;
            if (next <= 0) { if (b.Root.gameObject.activeSelf) b.Root.gameObject.SetActive(false); b.Key​ = [скрыто]; b.N = 0; return; }
            int unit = next > SegMax ? 5 : 1;
            int groups = (next + unit - 1) / unit;
            int from = groups > SegMax ? Mathf.Clamp(lv / unit - 1, 0, groups - SegMax) : 0;
            int n = Mathf.Min(groups, SegMax);
            string key​ = lv + "/" + cap + "/" + next;
            if (!b.Root.gameObject.activeSelf) b.Root.gameObject.SetActive(true);
            if (key​ == b.Key​) return;
            b.Key​ = [скрыто]; b.From = from; b.N = n; b.Unit = unit;
            float x = -265f + SegW * 0.5f;
            for (int i = 0; i < SegMax; i++)
            {
                var im = b.Seg[i];
                bool on = i < n;
                if (im.gameObject.activeSelf != on) im.gameObject.SetActive(on);
                if (!on) { b.State[i] = ' '; continue; }
                int lo = (from + i) * unit, hi = Mathf.Min(next, lo + unit);
                char st = hi <= lv ? 'g' : lo < cap ? 's' : 'l';
                b.State[i] = st;
                im.rectTransform.anchoredPosition = new Vector2(x, 0f);
                im.color = st == 'g' ? green : st == 's' ? _segFree : _segLock;
                b.Lock[i].gameObject.SetActive(st == 'l');
                float part = st != 'g' && lv > lo ? (lv - lo) / (float)(hi - lo) : 0f;
                var fr = b.Fill[i].rectTransform;
                b.Fill[i].gameObject.SetActive(part > 0f);
                if (part > 0f) { fr.sizeDelta = new Vector2(SegW * part, SegH); fr.anchoredPosition = new Vector2(-SegW * 0.5f * (1f - part), 0f); }
                x += SegW + SegGap + (unit == 1 && (from + i) % 5 == 4 ? SegGroupGap : unit > 1 ? 2f : 0f);
            }
        }

'''
s=s[:a]+new+s[b:]
s=s.replace('''            public Image[] Lock;
            public char[] State;
            public string Key;
            public int From, N;''','''            public Image[] Lock, Fill;
            public char[] State;
            public string Key​;
            public int From, N, Unit = 1;''')
open(p,'w',encoding='utf-8').write(s)
EOF
grep -n 'Unit = 1\|b.Fill\[i\]' OnePit/Ui/HallUpgSheet.cs | head

